interface INotifier { void Send(string recipient, string message); }
sealed class WelcomeService(INotifier notifier)
{
    public void Welcome(string name) => notifier.Send(name, "Welcome");
}
sealed class ConsoleMail : INotifier
{
    public void Send(string recipient, string message) => Console.WriteLine($"mail:{recipient}:{message}");
}
sealed class ConsoleSms : INotifier
{
    public void Send(string recipient, string message) => Console.WriteLine($"sms:{recipient}:{message}");
}

