foreach (var result in new[] { ChargeResult.Accepted, ChargeResult.Declined })
{
    var checkout = new Checkout(new FakeGateway(result));
    bool paid = checkout.Pay(120);
    Console.WriteLine($"{result}:paid={paid}");
}
enum ChargeResult { Accepted, Declined }
interface IPaymentGateway { ChargeResult Charge(int points); }
sealed class FakeGateway(ChargeResult result) : IPaymentGateway
{
    public ChargeResult Charge(int points)
    {
        if (points <= 0) throw new ArgumentOutOfRangeException(nameof(points));
        return result;
    }
}
sealed class Checkout(IPaymentGateway gateway)
{
    public bool Pay(int points)
    {
        if (points <= 0) throw new ArgumentOutOfRangeException(nameof(points));
        return gateway.Charge(points) == ChargeResult.Accepted;
    }
}

