IReport[] reports = { new PlainReport("people"), new UpperReport("people") };
foreach (var report in reports) Console.WriteLine(report.Render(new[] { "An", "Binh" }));
interface IReport { string Render(string[] rows); }
abstract class Report(string title) : IReport
{
    public string Render(string[] rows)
    {
        ArgumentNullException.ThrowIfNull(rows);
        return title + ":" + string.Join(";", rows.Select(Format));
    }
    protected abstract string Format(string row);
}
sealed class PlainReport(string title) : Report(title)
{
    protected override string Format(string row) => row;
}
sealed class UpperReport(string title) : Report(title)
{
    protected override string Format(string row) => row.ToUpperInvariant();
}

